  package    org . sonar . plugins . ldap ;   import   org . junit . ClassRule ;  import   org . junit . Test ;  import     org . sonar . api . config . Settings ;  import     org . sonar . api . security . UserDetails ;  import      org . sonar . plugins . ldap . server . LdapServer ;  import static     org . fest . assertions . Assertions . assertThat ;   public class LdapUsersProviderTest  {   public static final String  USERS_EXAMPLE_ORG_LDIF = "/users.example.org.ldif" ;   public static final String  USERS_INFOSUPPORT_COM_LDIF = "/users.infosupport.com.ldif" ;    @ ClassRule public static LdapServer  exampleServer =  new LdapServer  ( USERS_EXAMPLE_ORG_LDIF ) ;    @ ClassRule public static LdapServer  infosupportServer =  new LdapServer  ( USERS_INFOSUPPORT_COM_LDIF , "infosupport.com" , "dc=infosupport,dc=com" ) ;    @ Test public void test  ( )  throws Exception  {  Settings  settings =  LdapSettingsFactory . generateSimpleAnonymousAccessSettings  ( exampleServer , infosupportServer ) ;  LdapSettingsManager  settingsManager =  new LdapSettingsManager  ( settings ) ;  LdapUsersProvider  usersProvider =  new LdapUsersProvider  (  settingsManager . getContextFactories  ( ) ,  settingsManager . getUserMappings  ( ) ) ;  UserDetails  details ;   details =  usersProvider . doGetUserDetails  ( "godin" ) ;    assertThat  (  details . getName  ( ) ) . isEqualTo  ( "Evgeny Mandrikov" ) ;    assertThat  (  details . getEmail  ( ) ) . isEqualTo  ( "godin@example.org" ) ;   details =  usersProvider . doGetUserDetails  ( "tester" ) ;    assertThat  (  details . getName  ( ) ) . isEqualTo  ( "Tester Testerovich" ) ;    assertThat  (  details . getEmail  ( ) ) . isEqualTo  ( "tester@example.org" ) ;   details =  usersProvider . doGetUserDetails  ( "without_email" ) ;    assertThat  (  details . getName  ( ) ) . isEqualTo  ( "Without Email" ) ;    assertThat  (  details . getEmail  ( ) ) . isEqualTo  ( "" ) ;   details =  usersProvider . doGetUserDetails  ( "notfound" ) ;    assertThat  ( details ) . isNull  ( ) ;   details =  usersProvider . doGetUserDetails  ( "robby" ) ;    assertThat  (  details . getName  ( ) ) . isEqualTo  ( "Robby Developer" ) ;    assertThat  (  details . getEmail  ( ) ) . isEqualTo  ( "rd@infosupport.com" ) ;   details =  usersProvider . doGetUserDetails  ( "testerInfo" ) ;    assertThat  (  details . getName  ( ) ) . isEqualTo  ( "Tester Testerovich" ) ;    assertThat  (  details . getEmail  ( ) ) . isEqualTo  ( "tester@infosupport.com" ) ; } }